item.command:
/bin/bash -lc "python3 - <<'PY'
import urllib.request,hashlib,json
base='https://raw.githubusercontent.com/openmm/openmm/53770948682c40bd460b39830d4e0f0fd3a4b868/'
for path in ['examples/benchmark.py','examples/5dfr_solv-cube_equil.pdb','wrappers/python/openmm/app/data/amber99sb.xml','wrappers/python/openmm/app/data/tip3p.xml']:
 try:
  b=urllib.request.urlopen(base+path,timeout=30).read()
  print(json.dumps({'path':path,'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}))
  if path.endswith('benchmark.py'):
   s=b.decode().splitlines()
   for i,line in enumerate(s):
    if any(x in line for x in ['5dfr','amber99sb','tip3p','LangevinMiddle','setConstraintTolerance','hydrogenMass','seconds','add_option']): print(str(i+1)+': '+line)
 except Exception as e: print(path,str(e))
PY"

